packages/dsh-lan-proxy/src/server/config.source:
/**
 * dsh-lan-proxy — 配置模型与校验。
 *
 * 单一事实源是 schema：DEFAULT_CONFIG 由它归一化空输入派生；校验器与提示文案平行于
 * 它维护，键集一致性由 config-matrix 门禁锁定（漂移即红）。
 */
import z from "schemastery";
import {
  DEFAULT_DEFLATE_POLICY,
  DEFAULT_OPTIONS,
  isLoopbackTarget,
  type DeflatePolicy,
} from "../../shared/interface.ts";

/**
 * WebSocket 压缩桥接默认路径白名单（dsh 0.1.2 起 api-gateway 拥有的 Remote 流
 * mux 端点）。单一事实源：Config schema 默认值、apply resolve() 兜底与
 * normalizeLegacyWsCompressPaths 的归一化目标均与本常量同源（客户端 placeholder
 * 属构建期注入的展示文案，值保持一致）。
 */
export const DEFAULT_WSS_COMPRESS_PATHS: readonly string[] = ["/api/remote.mux"];

/** 插件配置（loader 应用 schema 默认值后传入；apply 内仍有合并兜底）。 */
export interface LanProxyConfig {
  enabled?: boolean;
  host?: string;
  port?: number;
  /** HTTPS 监听开关（默认开启；与 HTTP 并存）。 */
  httpsEnabled?: boolean;
  /** HTTPS 监听端口（默认 3443）。 */
  httpsPort?: number;
  /** 自定义 TLS 证书 PEM 文件路径（可选；缺省自动生成自签名证书）。 */
  tlsCertFile?: string;
  /** 自定义 TLS 私钥 PEM 文件路径（可选；与 tlsCertFile 成对）。 */
  tlsKeyFile?: string;
  /** 自建 LAN CA 公钥 PEM 文件路径（可选，仅读；issue #911 设置页下发 iOS/Android/Windows 安装用）。 */
  tlsCaCertFile?: string;
  targetHost?: string;
  targetPort?: number;
  /** 启动时是否向终端打印监听横幅（LAN 访问地址等；默认 true）。 */
  printBanner?: boolean;
  /**
   * WebSocket 桥接总开关（默认 true，issue #552 解耦）。true = 所有 WS 升级
   * 一律走「终结 + 桥接」（ws 库自动代答上游 Ping + 30s 半开探活 + 按策略协商
   * 压缩）——保活成为默认基座能力，移动端切后台不再被上游心跳判死；false =
   * 走 TCP 字节透传（显式放弃保活与压缩，README 标注移动端断连风险）。
   * 与 wsCompressEnabled/wsCompressPaths 正交：压缩仅作用于桥接路径，清空
   * 压缩白名单/关闭压缩不再连带丢失保活。
   */
  wsBridgeEnabled?: boolean;
  /** WebSocket 压缩总开关（默认 true）：仅控制桥接路径上是否协商 permessage-deflate。 */
  wsCompressEnabled?: boolean;
  /** 参与 WebSocket 压缩桥接的路径白名单。 */
  wsCompressPaths?: string[];
  /** WebSocket 压缩协商策略（issue #308 防手机端连接异常）。
   *  - browser：浏览器段是否允许协商 permessage-deflate（false = 全局关闭压缩）；
   *  - uaDeny：UA 片段命中则强制不协商（iOS Safari 启用压缩即失败，
   *    uWebSockets.js #76 实证；默认拦截 iPhone/iPad/iPod，覆盖桌面 Chrome 等）。 */
  wsDeflatePolicy?: { browser?: boolean; uaDeny?: string[] };
  /** HTTP 响应压缩总开关（默认 true；合并自 dsh-gzip）。经 compression 中间件按 Accept-Encoding 协商，Brotli/gzip 双生效。 */
  httpCompressEnabled?: boolean;
  /** 压缩档位预设 0..3（默认 1 低）：0 默认 / 1 低 / 2 中 / 3 高，对 gzip 与 Brotli 同时生效。 */
  httpCompressLevel?: number;
  /**
   * 自动注入启动令牌（issue #380，默认 true）：LAN 设备首次访问 `GET /` 时
   * 由转发层自动补当前 dsh web launch token，上游铸造持久会话 cookie——固定
   * 局域网设备免手工拿 token（token 每次重启变化，只打印在本机终端）。
   * 开启 = 任何能网络到达本端口的客户端都免 token 获得完整控制权（等效信任
   * 整个 LAN）；关闭不吊销已发 cookie。详见 README「安全模型」。
   */
  injectToken?: boolean;
  /**
   * 向非回环页面声明 `ownsHost`（issue #856，默认 false）：**等同伪造上游拓扑
   * 事实位**。被服务页面本不该携带 `__DSH_TRANSPORT__`；开启后非回环页面会拿到
   * `{ ownsHost: true }`，上游据此把页面判为「Host 独占」而不再把设置面降级为
   * memory scope。被解锁的具体行为（设置持久化落盘、宿主原生「打开配置文件」）、
   * 远程页与本机页不再可区分的后果、关闭方法与 `ssh -L` 零伪造替代路径见 README
   * 「安全模型」。这是页面侧事实位声明，**不是服务端授权变化**。
   */
  ownsHostCompat?: boolean;
}

/** HTTP 压缩运行快照（issue #33 子项 3：GUI 可见的压缩生效状态）。 */
export interface HttpCompressSnapshot {
  /** 配置意图：HTTP 响应压缩开关。 */
  httpCompressEnabled: boolean;
  /** 压缩档位预设 0..3。 */
  httpCompressLevel: number;
  /** 是否实际挂载在存活转发器上（enabled 且配置开启且转发器监听中）。 */
  httpCompressMounted: boolean;
  /** 协商计数（compressed = 按协商压缩/计入口径，passthrough = 豁免直通）。 */
  httpCompressStats: { compressed: number; passthrough: number };
}

/** 插件配置，由同名 schemastery schema 校验，也用于 GUI 设置面板渲染。
 * 显式注解（TS2883：全局命名空间合并致推断类型声明发射不可移植）+ 末尾 as 收口
 * （合并后的 Mode 条件类型使直接赋值判红 TS2322；as 保持类型面，值面无变化）。 */
export const Config: z<LanProxyConfig> = z.object({
  /** 总开关。 */
  enabled: z.boolean().default(true),
  /** LAN 绑定地址。 */
  host: z.string().default(DEFAULT_OPTIONS.host),
  /** LAN 监听端口（不是固定值，默认 3081）。 */
  port: z.natural().max(65535).default(DEFAULT_OPTIONS.port),
  /** HTTPS 监听开关（默认开启；与 HTTP 并存，转发逻辑一致）。 */
  httpsEnabled: z.boolean().default(true),
  /** HTTPS 监听端口（默认 3443）。 */
  httpsPort: z.natural().max(65535).default(DEFAULT_OPTIONS.httpsPort),
  /**
   * 自定义 TLS 证书 PEM 文件路径（可选）。提供 tlsCertFile + tlsKeyFile
   * 时使用该证书（正式证书 / mkcert 本地 CA 证书）；缺省时自动生成
   * 自签名证书并缓存到 <DSH_HOME>/lan-proxy/。
   */
  tlsCertFile: z.string(),
  /** 自定义 TLS 私钥 PEM 文件路径（可选；与 tlsCertFile 成对）。 */
  tlsKeyFile: z.string(),
  /**
   * 自建 LAN CA 公钥 PEM 文件路径（可选，仅读）。提供时设置页可下发 CA 证书
   * 供移动设备安装信任（issue #911）；缺省时设置页不下发（#930 Phase 1：自签
   * 模式与自定义叶子无 CA 一律 404）。无默认值（同 tlsCertFile 系）。
   */
  tlsCaCertFile: z.string(),
  /** 回环上游主机。 */
  targetHost: z.string().default(DEFAULT_OPTIONS.targetHost),
  /**
   * 上游端口；缺省时取 web 服务器实际绑定端口（ctx.webServer.port），
   * 因此无需配置即可跟随 `--port` 变化。schemastery 中不带 `.required()`
   * 的字段默认可选（3.18 无 `.optional()` 方法）。
   */
  targetPort: z.natural().max(65535),
  /** 启动横幅（终端 console.log；默认开，可经 GUI 设置面板关闭）。 */
  printBanner: z.boolean().default(true),
  /**
   * WebSocket 桥接总开关（默认 true，issue #552 解耦）：true = 所有 WS 升级
   * 一律走「终结 + 桥接」（ws 库自动代答上游 Ping + 30s 半开探活 + 按策略协商
   * 压缩）——保活成为默认基座能力，移动端切后台不再被上游心跳判死；false =
   * 走 TCP 字节透传（显式放弃保活与压缩，README 标注移动端断连风险）。
   * 与 wsCompressEnabled/wsCompressPaths 正交：压缩仅作用于桥接路径。
   */
  wsBridgeEnabled: z.boolean().default(true),
  /**
   * WebSocket 压缩总开关（默认开）：仅控制桥接路径上是否协商 permessage-deflate
   * （浏览器段压缩、DSH 段明文），大流量 Remote 流 mux 通道（remote.mux）
   * 经远程/慢链路访问时显著省流量。关闭压缩不影响桥接保活（issue #552）。
   */
  wsCompressEnabled: z.boolean().default(true),
  /** 参与 WebSocket 压缩桥接的路径白名单（默认：api-gateway 的 Remote 流 mux 端点）。 */
  wsCompressPaths: z.array(z.string()).default([...DEFAULT_WSS_COMPRESS_PATHS]),
  /**
   * WS 压缩协商策略（默认：浏览器段可协商，但 iPhone/iPad/iPod UA 强制不协商——
   * iOS Safari 启用 permessage-deflate 即失败，uWebSockets.js #76 实证，issue #308）。
   * browser=false 全局关压缩；uaDeny 片段命中即降级为明文帧（对这类端省去
   * compress 字节流的解压负担，连接更稳）。热更新经 scope.watch 生效。
   */
  wsDeflatePolicy: z
    .object({
      browser: z.boolean().default(true),
      uaDeny: z.array(z.string()).default([...(DEFAULT_DEFLATE_POLICY.uaDeny ?? [])]),
    })
    .default({
      browser: DEFAULT_DEFLATE_POLICY.browser ?? true,
      uaDeny: [...(DEFAULT_DEFLATE_POLICY.uaDeny ?? [])],
    }),
  /**
   * HTTP 响应 gzip 压缩总开关（默认开；合并自 dsh-gzip）：对 /api、/plugins、
   * 静态资源等可压缩响应做应用层 gzip。安装失败仅 warn 降级，不阻断转发。
   */
  httpCompressEnabled: z.boolean().default(true),
  /** 压缩档位预设 0..3（默认 1 低）：0 默认 / 1 低 / 2 中 / 3 高，对 gzip 与 Brotli 同时生效（见 proxy.resolveCompressionOptions 映射）。 */
  httpCompressLevel: z.natural().max(3).default(1),
  /**
   * 自动注入启动令牌（默认开，issue #380）：LAN 设备首次访问 `GET /` 由转发层
   * 自动补当前 launch token 铸造会话 cookie，固定设备免手工拿 token。安全语义
   * 见 README「安全模型」——开启等效把 LAN 视为可信网络。
   */
  injectToken: z.boolean().default(true),
  /**
   * 向非回环页面声明 `ownsHost`（默认关，issue #856）：伪造上游拓扑事实位的
   * 兼容开关，解锁面与替代路径见 README「安全模型」。
   */
  ownsHostCompat: z.boolean().default(false),
  // 末尾 as 收口（见文件头注释）：合并后的 Mode 条件类型使直接赋值判红，
  // as 保持对外类型面恒为 z<LanProxyConfig>，值面无任何变化。
}) as z<LanProxyConfig>;

/** 整节标记 volatile： hot 更新免 remount。直接置 meta（链式写法在锁版 schemastery 无此方法）。 */
(Config as unknown as { meta: { volatile?: boolean } }).meta.volatile = true;

/**
 * 默认配置（键集 = schema 中带 `.default()` 的字段）。从 schema 归一化**空输入**派生，
 * 不再手写第二份默认值——默认值只写在上面 schema 的 `.default(...)` 里，改一处即改两处。
 *
 * 为什么「归一化空输入」就是默认值：schemastery 对未带默认值的字段（tlsCertFile /
 * tlsKeyFile / tlsCaCertFile / targetPort）在结果里直接省略，故本对象的键集比 schema 字段数少 4。这是
 * 事实而非缺口——config-matrix 门禁的 N1/N2 正是锁这条不变式（键集与 normalizeConfig({}) 全等）。
 */
export const DEFAULT_CONFIG: LanProxyConfig = Config({});

/**
 * apply 的 resolve() 缺省兜底后的一份完整生效配置（**缺省值的事实源**）。
 *
 * 基础取 DEFAULT_CONFIG（= Config({})，schema 的缺省即此），再把 ResolvedConfig 里那 14 个
 * **必填**键的缺省显式补上——`z<LanProxyConfig>` 这个注解把 schema 的缺填性擦成了全可选，
 * 故 DEFAULT_CONFIG 的静态类型读不出「这些键恒有值」，只能在这里按域分组补一遍。
 * 两组与原先 resolve() 里的注释分组一致：监听面（地址/端口/上游/横幅）与投递面
 * （桥接/压缩/令牌/host trust）。tlsCertFile / tlsKeyFile / tlsCaCertFile / targetPort 无
 * `.default()`，故不在必填集里——缺省即 undefined。
 *
 * 为什么不在 apply 的 resolve() 里逐键 `??`：那份写法把每个键的缺省抄在 resolve 里，域内加一个
 * 带 `.default()` 的键却忘了在 resolve 补一条 `??`，症状是该键以 undefined 直达转发器（而不是
 * 落到缺省）。缺省现在只有这一处，且与 schema 同域。
 */
export const RESOLVED_DEFAULTS: ResolvedConfig = {
  ...DEFAULT_CONFIG,
  ...listenDefaults(),
  ...deliveryDefaults(),
};

/** 监听面那七项的缺省（ResolvedConfig 里它们是必填，故此处返回类型也是必填）。 */
type ListenDefaults = Pick<
  ResolvedConfig,
  "enabled" | "host" | "port" | "httpsEnabled" | "httpsPort" | "targetHost" | "printBanner"
>;

/** 投递面那八项的缺省（同上：必填）。 */
type DeliveryDefaults = Pick<
  ResolvedConfig,
  | "wsBridgeEnabled"
  | "wsCompressEnabled"
  | "wsCompressPaths"
  | "wsDeflatePolicy"
  | "httpCompressEnabled"
  | "httpCompressLevel"
  | "injectToken"
  | "ownsHostCompat"
>;

/** 监听面缺省：开关 / 绑定地址 / 两个端口 / 上游 / 启动横幅。 */
function listenDefaults(): ListenDefaults {
  return {
    enabled: DEFAULT_CONFIG.enabled ?? true,
    host: DEFAULT_CONFIG.host ?? DEFAULT_OPTIONS.host,
    port: DEFAULT_CONFIG.port ?? DEFAULT_OPTIONS.port,
    httpsEnabled: DEFAULT_CONFIG.httpsEnabled ?? true,
    httpsPort: DEFAULT_CONFIG.httpsPort ?? DEFAULT_OPTIONS.httpsPort,
    targetHost: DEFAULT_CONFIG.targetHost ?? DEFAULT_OPTIONS.targetHost,
    printBanner: DEFAULT_CONFIG.printBanner ?? true,
  };
}

/** 投递面缺省：WS 桥接与压缩 / HTTP 压缩 / launch 令牌注入 / host trust 兼容开关。
 *
 * 桥接总开关（issue #552 解耦）：默认 true 实现在 resolve 接线层——createLanProxy 参数层不设
 * 默认，保证 smoke/unit 现有无参/旧参调用行为不变（透传升级测试不意外走桥接）。
 * host trust 兼容开关（issue #856）：默认关；tap 内逐请求读取 resolve() 结果。
 */
function deliveryDefaults(): DeliveryDefaults {
  return {
    wsBridgeEnabled: DEFAULT_CONFIG.wsBridgeEnabled ?? true,
    wsCompressEnabled: DEFAULT_CONFIG.wsCompressEnabled ?? true,
    wsCompressPaths: DEFAULT_CONFIG.wsCompressPaths ?? DEFAULT_WSS_COMPRESS_PATHS,
    wsDeflatePolicy: DEFAULT_CONFIG.wsDeflatePolicy ?? DEFAULT_DEFLATE_POLICY,
    httpCompressEnabled: DEFAULT_CONFIG.httpCompressEnabled ?? true,
    httpCompressLevel: DEFAULT_CONFIG.httpCompressLevel ?? 1,
    injectToken: DEFAULT_CONFIG.injectToken ?? true,
    ownsHostCompat: DEFAULT_CONFIG.ownsHostCompat ?? false,
  };
}

/**
 * 归一化：把未知输入按 schema 校验并补默认值。
 * 与 `sanitizeSettings` 分工不同：本函数用于「给出一份完整配置」，后者用于「判断客户端
 * 提交的 patch 是否可信」（只做已知键 + 类型合法过滤，不补默认值）。
 */
export function normalizeConfig(input: unknown): LanProxyConfig {
  // 输入来自外部（配置文件 / 客户端 patch），运行时由 schema 校验并补默认值；
  // 断言只表达「这里是 schema 的入口」，不是「已信任」。
  return Config(input as LanProxyConfig | undefined);
}

/** 只接受布尔值的配置键（客户端 UI 按它渲染开关）；与 schema 里的 `z.boolean()` 字段一一对应。 */
export const BOOLEAN_KEYS: readonly string[] = [
  "enabled",
  "httpsEnabled",
  "printBanner",
  "wsBridgeEnabled",
  "wsCompressEnabled",
  "httpCompressEnabled",
  "injectToken",
  "ownsHostCompat",
];

/**
 * 非负整数键及其上界（默认值不得越界）。上界与 schema 里的 `.max(...)` 同值——两处都是
 * 声明，config-matrix 门禁的 N4 断言它们与 DEFAULT_CONFIG 一致，漂移即红。
 * `targetPort` 不在列：它无默认值、默认配置的键集里没有它（见上）。
 */
export const COUNT_LIMITS: Record<string, number> = {
  port: 65535,
  httpsPort: 65535,
  httpCompressLevel: 3,
};

/**
 * 允许的配置键及其类型校验（未知键/类型非法一律丢弃）。
 * 双重身份（issue #110 后）：① 存量 config.json 迁移过滤器；
 * ② 客户端提交 patch 的校验器。键集合与 SETTING_FIELD_HINTS 平行维护。
 */
const FILE_CONFIG_VALIDATORS: Record<string, (v: unknown) => boolean> = {
  enabled: (v) => typeof v === "boolean",
  host: (v) => typeof v === "string",
  port: (v) => typeof v === "number" && Number.isInteger(v) && v > 0 && v <= 65535,
  httpsEnabled: (v) => typeof v === "boolean",
  httpsPort: (v) => typeof v === "number" && Number.isInteger(v) && v > 0 && v <= 65535,
  tlsCertFile: (v) => typeof v === "string",
  tlsKeyFile: (v) => typeof v === "string",
  tlsCaCertFile: (v) => typeof v === "string",
  targetHost: (v) => typeof v === "string" && isLoopbackTarget(v),
  targetPort: (v) => typeof v === "number" && Number.isInteger(v) && v > 0 && v <= 65535,
  printBanner: (v) => typeof v === "boolean",
  wsBridgeEnabled: (v) => typeof v === "boolean",
  wsCompressEnabled: (v) => typeof v === "boolean",
  wsCompressPaths: (v) => Array.isArray(v) && v.every((s) => typeof s === "string"),
  wsDeflatePolicy: (v) => {
    if (typeof v !== "object" || v === null) return false;
    const rec = v as Record<string, unknown>;
    return (
      (rec.browser === undefined || typeof rec.browser === "boolean") &&
      (rec.uaDeny === undefined ||
        (Array.isArray(rec.uaDeny) && rec.uaDeny.every((s) => typeof s === "string")))
    );
  },
  httpCompressEnabled: (v) => typeof v === "boolean",
  httpCompressLevel: (v) => typeof v === "number" && Number.isInteger(v) && v >= 0 && v <= 3,
  injectToken: (v) => typeof v === "boolean",
  ownsHostCompat: (v) => typeof v === "boolean",
};

/**
 * 净化提交的配置（迁移过滤与客户端保存共用）：只接受已知键；任一键类型非法 →
 * 整体拒绝（返回 null，避免静默丢键造成"保存了但没生效"的困惑）；空字符串
 * 证书路径被剔除（保存通道据 raw 判定清除语义，迁移场景等价于未设置）。
 */
export function sanitizeSettings(raw: unknown): Partial<LanProxyConfig> | null {
  if (typeof raw !== "object" || raw === null) return null;
  const src = raw as Record<string, unknown>;
  const out: Partial<LanProxyConfig> = {};
  for (const key of Object.keys(FILE_CONFIG_VALIDATORS)) {
    const value = migrateSettingValue(key, src[key]);
    if (value === undefined || value === null) continue;
    if (!FILE_CONFIG_VALIDATORS[key](value)) return null;
    // 空字符串证书路径被剔除（保存通道据 raw 判定清除语义，迁移场景等价于未设置）
    if (isCertPathKey(key) && value === "") continue;
    (out as Record<string, unknown>)[key] = value;
  }
  return out;
}

/**
 * 旧档位迁移：整数 4..9 视为「高」档（3）。只有 httpCompressLevel 一键有迁移。
 *
 * sanitizeSettings 与 validateSettings **共用这一份**：两处原先各写一遍同口径的迁移，
 * 「同口径」靠注释维系，改一侧漏另一侧的症状是「保存过了但校验报非法」。
 */
function migrateSettingValue(key: string, value: unknown): unknown {
  if (key !== "httpCompressLevel") return value;
  return typeof value === "number" && Number.isInteger(value) && value > 3 && value <= 9
    ? 3
    : value;
}

/** 三个证书路径键（空串在净化面被剔除，在校验面按非法处理）。 */
function isCertPathKey(key: string): boolean {
  return key === "tlsCertFile" || key === "tlsKeyFile" || key === "tlsCaCertFile";
}

/**
 * 旧版默认 WS 压缩白名单（dsh 0.1.2 之前的事件流端点对）。显式保存过该值的
 * settings 用户层升级后原样保留，`/api/remote.mux` 不再命中 → 压缩静默失效
 * （issue #395 M2 根因）。
 */
const LEGACY_WSS_COMPRESS_PATHS: readonly string[] = ["/api/events.mux", "/api/events.host"];

/**
 * 存量 WS 压缩白名单归一化（issue #395 M2）：当白名单与旧默认
 * LEGACY_WSS_COMPRESS_PATHS 无序等价（忽略顺序、元素完全一致）时，归一化为
 * 新默认 DEFAULT_WSS_COMPRESS_PATHS（与 schema 默认值/客户端 placeholder 同源）；
 * 否则原样返回——undefined、空数组、含自定义路径的组合一律不做改写（尊重用户
 * 自定义，含废弃端点的自定义白名单同样保留）。导出供 resolve()、
 * migrateFileConfig() 与单测复用。
 */
export function normalizeLegacyWsCompressPaths(
  paths: readonly string[] | undefined,
): readonly string[] | undefined {
  if (paths === undefined) return undefined;
  if (paths.length !== LEGACY_WSS_COMPRESS_PATHS.length) return paths;
  const rest = new Set(LEGACY_WSS_COMPRESS_PATHS);
  for (const path of paths) {
    if (!rest.has(path)) return paths;
    rest.delete(path);
  }
  return [...DEFAULT_WSS_COMPRESS_PATHS];
}

/**
 * 各配置键的合法范围描述（issue #33 子项 1）：校验失败时向用户指明
 * 「哪个字段、合法值是什么」，替代原先硬编码的整体拒绝文案。
 * 与 FILE_CONFIG_VALIDATORS 平行维护；键集合一致（同一批 Object.keys 遍历）。
 */
const SETTING_FIELD_HINTS: Record<string, string> = {
  enabled: "需为布尔值",
  host: "需为字符串",
  port: "需为 1-65535 的整数",
  httpsEnabled: "需为布尔值",
  httpsPort: "需为 1-65535 的整数",
  tlsCertFile: "需为字符串（PEM 文件路径，留空 = 自签名证书）",
  tlsKeyFile: "需为字符串（PEM 文件路径，留空 = 自签名证书）",
  tlsCaCertFile: "需为字符串（CA 公钥 PEM 文件路径，留空 = 不下发 CA）",
  targetHost: "需为回环地址或主机名",
  targetPort: "需为 1-65535 的整数",
  printBanner: "需为布尔值",
  wsBridgeEnabled: "需为布尔值（WS 桥接总开关：true=全部 WS 走桥接保活，false=透传）",
  wsCompressEnabled: "需为布尔值",
  wsCompressPaths: "需为字符串数组（路径白名单）",
  wsDeflatePolicy: "需为 { browser?: boolean, uaDeny?: string[] }（UA 片段数组）",
  httpCompressEnabled: "需为布尔值",
  httpCompressLevel: "需为 0-3 的档位整数（4-9 自动迁移为高档 3）",
  injectToken: "需为布尔值",
  ownsHostCompat: "需为布尔值（向非回环页面声明 ownsHost：伪造上游拓扑事实位）",
};

/** validateSettings 的校验结果：null = 全部合法。 */
export interface SettingInvalid {
  /** 首个非法的配置键名。 */
  key: string;
  /** 该键的合法范围描述（面向用户的文案）。 */
  hint: string;
}

/**
 * 校验客户端提交的配置（不净化）：返回首个非法键与其合法范围，全部合法返回
 * null（issue #33 子项 1）。遍历顺序与 sanitizeSettings 一致（FILE_CONFIG_VALIDATORS
 * 键序），保证「首个非法键」口径相同。导出供 smoke 单测。
 */
export function validateSettings(raw: unknown): SettingInvalid | null {
  if (typeof raw !== "object" || raw === null) return { key: "(payload)", hint: "需为配置对象" };
  const src = raw as Record<string, unknown>;
  for (const key of Object.keys(FILE_CONFIG_VALIDATORS)) {
    // 与 sanitizeSettings 共用 migrateSettingValue：旧档位整数 4..9 先迁移再校验。
    const normalized = migrateSettingValue(key, src[key]);
    if (normalized === undefined || normalized === null) continue;
    if (!FILE_CONFIG_VALIDATORS[key](normalized)) {
      return { key, hint: SETTING_FIELD_HINTS[key] ?? "类型非法" };
    }
  }
  return null;
}

/** resolve() 合并后的完整生效配置（GET /config 的 effective 展示用）。 */
export interface ResolvedConfig {
  enabled: boolean;
  host: string;
  port: number;
  httpsEnabled: boolean;
  httpsPort: number;
  tlsCertFile?: string;
  tlsKeyFile?: string;
  tlsCaCertFile?: string;
  targetHost: string;
  targetPort?: number;
  printBanner: boolean;
  /** WS 桥接总开关（issue #552；默认 true，见 apply resolve）。 */
  wsBridgeEnabled: boolean;
  wsCompressEnabled: boolean;
  wsCompressPaths: readonly string[];
  wsDeflatePolicy: DeflatePolicy;
  httpCompressEnabled: boolean;
  httpCompressLevel: number;
  /** 自动注入启动令牌（issue #380；默认 true）。 */
  injectToken: boolean;
  /** 向非回环页面声明 `ownsHost`（issue #856；默认 false）。 */
  ownsHostCompat: boolean;
}

/**
 * dsh-lan-proxy — 官方 settings 条目接线（薄包装）。
 *
 * 只做三件事：注册条目、把 owner scope 交给调用方、依次透传 hooks；实现统一
 * 转发 shared/installSettingsNamespace（单一事实源）。
 *
 * 为什么不用官方 @deepseek-ai/dsh-settings 包：插件运行时沿自身 lib/ 向上解析不到
 * 该包（MODULE_NOT_FOUND），动态 import 会静默失败。
 *
 * 读面以 describe 的 descriptor 为准（user/revision），写面走 owner scope.update/replace，
 * 热更新订阅 settings/document-updated（见 apply）。
 */
import type { Context } from "@deepseek-ai/cordis";
import { installSettingsNamespace } from "../../../../../../shared/settings-namespace.js";
import { LAN_PROXY_IDENTITY } from "../../../shared/interface.ts";
import { Config } from "./model.ts";
import type { LanProxyConfig } from "./model.ts";

export { warnLog } from "../../../../../../shared/settings-namespace.js";

/** 本插件在官方 settings 服务中的 canonical 条目 id。 */
export const SETTINGS_NS = LAN_PROXY_IDENTITY.settingsNamespace;

/** describe 返回的条目 descriptor 最小面。 */
export interface SettingsDescriptorLike {
  /** 条目 id。 */
  ns: string;
  /** 原始 user 节（存在即用户设过值）。 */
  user?: unknown;
  /** 乐观并发版本。 */
  revision: number;
}

/** owner scope 最小类型面（以 describe 投影读、以 update/replace 写）。 */
export interface OwnerScopeLike {
  /** 当前解析值（schema defaults → base → user 层）。 */
  get(): LanProxyConfig;
  /** 增量 merge patch 进 user 层并持久化。 */
  update(patch: object, expectedRevision?: number): Promise<void>;
  /** 整节替换 user 层，缺省键回落 base/schema 默认。 */
  replace(section: object, expectedRevision?: number): Promise<void>;
}

/** settings 服务最小类型面。 */
export interface SettingsServiceLike {
  /** 条目描述（wire 面必传 redactSecrets）。 */
  describe(options?: { redactSecrets?: boolean }): Array<SettingsDescriptorLike>;
  /** 服务级增量写。 */
  update?(ns: string, patch: object, expectedRevision?: number): Promise<void>;
  /** 服务级整节替换。 */
  replace?(ns: string, section: object, expectedRevision?: number): Promise<void>;
}

/** installLanProxySettings 的 hooks 面（含 onScope：attach 后交出 owner scope）。 */
export interface LanProxySettingsHooks {
  /** 把插件对该条目的读取来源指向返回的 scope（见实现：scope.get）。 */
  setSource(source: () => LanProxyConfig): void;
  /** 来源切换或条目值变化时触发，插件据此刷新/重建转发器。 */
  onChange(): void;
  /** scope attach 后回调（迁移在此执行）；服务缺失时不触发。 */
  onScope(scope: OwnerScopeLike, service: SettingsServiceLike): void;
}

/**
 * 注册插件自有 settings 条目并把 owner scope 交给调用方。
 * 薄包装（#436）：转发 shared/installSettingsNamespace——setSource / onChange /
 * onScope 依次透传，降级与卸载回落语义统一由 shared 承担。对外签名与 #436 前
 * 保持一致：ctx / entry（组合层配置，作为条目的 base 层）/ hooks。
 *
 * @param ctx - 插件宿主端 apply 收到的 cordis 上下文。
 * @param entry - 组合层配置，作为条目的 base 层。
 * @param hooks - source 收藏、变更通知与 scope 移交。
 */
export function installLanProxySettings(
  ctx: Context,
  entry: LanProxyConfig,
  hooks: LanProxySettingsHooks,
): void {
  installSettingsNamespace(ctx, SETTINGS_NS, Config, entry, {
    setSource: hooks.setSource,
    onChange: hooks.onChange,
    onScope: hooks.onScope,
  });
}

/**
 * dsh-lan-proxy — loopback HTTP 配置面。
 *
 * 路由表（ROUTES）与保存纯函数（applyConfigPatch）同处：两者只服务配置读写，
 * 且 ROUTES 是与客户端共享的来源（构建期经 __DSH_ROUTES__ 注入）。
 */
import {
  writeJson,
  readBody,
  errorMessage,
  guardLoopbackMethod,
} from "../../../../../../shared/host-utils.js";
import type { WebRoute } from "@deepseek-ai/dsh-host-webserver";
import { sanitizeSettings, validateSettings } from "./model.ts";
import type { HttpCompressSnapshot, ResolvedConfig } from "./model.ts";
import type { DownloadCertResult } from "../../tls/interface.ts";

/** 与客户端共享的路由（单一来源；客户端经 shared/contract.ts 镜像 + __DSH_ROUTES__ 注入消费）。 */
export const ROUTES = {
  health: "/api/dsh-lan-proxy/health",
  /** 配置读写路由：GET 快照 / PUT patch（loopback 围栏）。 */
  config: "/api/dsh-lan-proxy/config",
  /** CA/自签证书下发路由：GET 只读（loopback 围栏；issue #911 移动设备安装信任用）。 */
  caCert: "/api/dsh-lan-proxy/ca-cert",
  /**
   * 一键 CA 动作路由：POST 只写（loopback 围栏；#930 Phase 2 自签首建 / 托管轮换）。
   * 处理器归 ca 域（buildCaActionRoutes），本表只收路径名（F16 ROUTES 单源；
   * 本文件头“只服务配置读写”指处理器归属，路径名作为共享来源例外——caCert
   * 路由同例：路径在此、语义在 tls 域）。
   */
  caGenerate: "/api/dsh-lan-proxy/ca/generate",
};

/** buildConfigRoutes 的依赖注入面（apply 内装配；smoke 用 fake 直接构造）。 */
export interface ConfigRouteDeps {
  /** 当前生效配置（含默认值兜底）。 */
  resolve(): ResolvedConfig;
  /** 用户层原始节与 revision（descriptor.user / descriptor.revision）。 */
  readUser(): { user: Record<string, unknown>; revision?: number };
  /** settings 服务是否可用（决定 PUT 是否可写）。 */
  writable(): boolean;
  /** 增量 merge patch 进用户层。 */
  update(patch: object, expectedRevision?: number): Promise<void>;
  /** 整节替换用户层（清除证书路径的 unset 语义）。 */
  replace(section: object, expectedRevision?: number): Promise<void>;
  /** HTTP 压缩运行快照。 */
  compress(): HttpCompressSnapshot;
  /** 服务端日志兜底（写入异常原文只进日志，不进响应 details）。 */
  logWarn?(message: string): void;
}

/** applyConfigPatch 的结果。 */
export type PatchResult =
  | { ok: true; value: { user: Record<string, unknown>; revision?: number } }
  | { ok: false; status: number; code: string; details: string };

/** 清除证书路径时需要从用户层剔除的键（空字符串 = 显式清除，恢复自签名）。 */
const TLS_PAIR_KEYS = ["tlsCertFile", "tlsKeyFile"] as const;

/** CA 公钥路径键（issue #911）：独立清除，不与 leaf/key 成对绑定（空字符串 = 显式清除）。 */
const CA_CERT_KEY = "tlsCaCertFile";

/** PUT 负载包络：raw patch、期望版本与 raw 键视图（三处共用同一空对象回退口径）。 */
interface PatchEnvelope {
  readonly rawPatch: unknown;
  readonly expectedRevision: number | undefined;
  readonly rawSrc: Record<string, unknown>;
}

/** 解析 PUT 负载包络（原 applyConfigPatch 首段：body 回退 + 版本归一化 + raw 视图）。 */
function extractPatchEnvelope(payload: unknown): PatchEnvelope {
  const body = (typeof payload === "object" && payload !== null ? payload : {}) as {
    patch?: unknown;
    expectedRevision?: unknown;
  };
  const expectedRevision =
    typeof body.expectedRevision === "number" && Number.isInteger(body.expectedRevision)
      ? body.expectedRevision
      : undefined;
  const rawPatch = body.patch;
  const rawSrc = (typeof rawPatch === "object" && rawPatch !== null ? rawPatch : {}) as Record<
    string,
    unknown
  >;
  return { rawPatch, expectedRevision, rawSrc };
}

/** TLS 成对错误（两层共用同一文案与状态码）。 */
function tlsPairError(): PatchResult {
  return {
    ok: false,
    status: 400,
    code: "tls-pair",
    details: "证书文件与私钥文件必须成对提供（或都留空以使用自签名证书）",
  };
}

/**
 * 证书成对约束（#467 固化成对语义）：raw 层按「键是否显式出现」判定形态——
 * 只显式给出单侧（另一侧未提交 = undefined）即拒绝；"一空一缺"与"一非空一缺"
 * 同属单侧出现。注意须用键存在性（rawSrc[key] !== undefined）而非字符串判型：
 * 单侧显式空串意在清除，另一侧缺席时若漏判会进入 clearingTls 分支，删除循环
 * 只剔"显式空串"侧，user 层残留另一侧孤儿（半套证书）。"同空（双空串）"=
 * 整套清除、"同非空"= 整套设置，均两侧同时显式出现，不落此分支。
 * 成对约束第二层（sanitize 后判定，口径与历史版本一致）：只给单侧值。
 * 返回 undefined 表示通过，否则为直接返回的错误结果。
 */
function checkTlsPair(
  rawSrc: Record<string, unknown>,
  sanitized: NonNullable<ReturnType<typeof sanitizeSettings>>,
): PatchResult | undefined {
  const rawCertExplicit = rawSrc.tlsCertFile !== undefined;
  const rawKeyExplicit = rawSrc.tlsKeyFile !== undefined;
  if (rawCertExplicit !== rawKeyExplicit) return tlsPairError();
  if (Boolean(sanitized.tlsCertFile) !== Boolean(sanitized.tlsKeyFile)) return tlsPairError();
  return undefined;
}

/**
 * 落盘 patch（原 applyConfigPatch 尾段：clearing 分流 + 写入 + 错误映射）。
 * 默认走 update 增量 merge；仅当 raw patch 以空字符串表达「清除证书路径」时
 * 走 replace（update 是 merge 语义无法 unset，owner scope 无 mutate 面）：
 * 从当前用户层复制全节、剔除被清除的键后整节替换，其余语义不变。
 */
async function persistPatchedConfig(
  deps: ConfigRouteDeps,
  sanitized: NonNullable<ReturnType<typeof sanitizeSettings>>,
  rawSrc: Record<string, unknown>,
  expectedRevision: number | undefined,
): Promise<PatchResult> {
  // #467 叶对：显式空串任一侧即整套剔除（raw 层已保证同空同现）。
  const clearingLeaf = TLS_PAIR_KEYS.some((key) => rawSrc[key] === "");
  // #911 CA：独立清除，不与叶对绑定（单清 CA 不得触碰叶子配置）。
  const clearingCa = rawSrc[CA_CERT_KEY] === "";
  try {
    if (clearingLeaf || clearingCa) {
      // update 是 merge 语义无法 unset，owner scope 无 mutate 面 → 走 replace：
      // 从当前用户层复制全节、剔除被清除的键后整节替换，其余语义不变。
      // readUser 整段只调一次（末尾回 value 时还要再调一次，那是返回值，不是这条路径）。
      const { user } = deps.readUser();
      await deps.replace(
        replacedSection(
          user,
          sanitized as Record<string, unknown>,
          rawSrc,
          clearingLeaf,
          clearingCa,
        ),
        expectedRevision,
      );
    } else {
      await deps.update(sanitized as Record<string, unknown>, expectedRevision);
    }
  } catch (err) {
    return writeFailureOf(deps, err);
  }
  return { ok: true, value: deps.readUser() };
}

/**
 * replace 用的整节：从用户层复制 → 剔除被清除的键 → 铺上净化后的 patch。
 *
 * 叶对的剔除条件是「raw 层显式空串 **或** 用户层本来就有」——后者覆盖「raw 给了新值但
 * 用户层残留旧空串」这类半迁移形态。CA 独立清除，不与叶对绑定（单清 CA 不得触碰叶子配置）。
 * 纯函数：读 user、给 raw，不碰 deps，故可被直接单测。
 */
function replacedSection(
  user: Record<string, unknown>,
  sanitized: Record<string, unknown>,
  rawSrc: Record<string, unknown>,
  clearingLeaf: boolean,
  clearingCa: boolean,
): Record<string, unknown> {
  const section: Record<string, unknown> = { ...user };
  if (clearingLeaf) {
    for (const key of TLS_PAIR_KEYS) {
      if (rawSrc[key] === "" || user[key] !== undefined) delete section[key];
    }
  }
  if (clearingCa) delete section[CA_CERT_KEY];
  return { ...section, ...sanitized };
}

/** 写入失败的对外映射：409 走冲突文案，其余收敛为固定 500 文案（原文只进日志）。 */
function writeFailureOf(deps: ConfigRouteDeps, err: unknown): PatchResult {
  const code = (err as { code?: unknown })?.code;
  if (code === "SETTINGS_CONFLICT") {
    return {
      ok: false,
      status: 409,
      code: "conflict",
      details: "设置已被其他窗口修改，请刷新后重试",
    };
  }
  // P2-2：对外收敛固定文案，不把底层异常原文（可能含路径等内部信息）回给
  // 客户端；完整原因走服务端日志。
  deps.logWarn?.(`lan-proxy: 配置保存写入设置存储失败 — ${errorMessage(err)}`);
  return { ok: false, status: 500, code: "error", details: "保存失败，请查看服务端日志" };
}

/**
 * 配置保存纯函数（PUT /config 的主体，独立导出供 smoke 单测）：
 * validate 定位首个非法键 → sanitize 净化 → tls 成对校验 → 写入官方存储。
 * 默认走 update 增量 merge；仅当 raw patch 以空字符串表达「清除证书路径」时
 * 走 replace（update 是 merge 语义无法 unset，owner scope 无 mutate 面）：
 * 从当前用户层复制全节、剔除被清除的键后整节替换，其余语义不变。
 */
export async function applyConfigPatch(
  deps: ConfigRouteDeps,
  payload: unknown,
): Promise<PatchResult> {
  if (!deps.writable()) {
    return {
      ok: false,
      status: 503,
      code: "settings-unavailable",
      details: "settings 服务不可用，无法保存配置",
    };
  }
  const { rawPatch, expectedRevision, rawSrc } = extractPatchEnvelope(payload);
  // 先定位首个非法键（issue #33 子项 1）：错误文案指明字段与合法范围。
  const invalid = validateSettings(rawPatch);
  if (invalid !== null) {
    return {
      ok: false,
      status: 400,
      code: "invalid",
      details: `配置项「${invalid.key}」非法：${invalid.hint}`,
    };
  }
  const sanitized = sanitizeSettings(rawPatch);
  if (sanitized === null) {
    return { ok: false, status: 400, code: "invalid", details: "非法配置值（未知键或类型错误）" };
  }
  const tlsErr = checkTlsPair(rawSrc, sanitized);
  if (tlsErr !== undefined) return tlsErr;
  return persistPatchedConfig(deps, sanitized, rawSrc, expectedRevision);
}

/**
 * 组装配置路由（GET 读快照 + PUT 写 patch；loopback 围栏 + 方法白名单）。
 * 导出供 smoke 单测（fake deps，不依赖网络）。
 */
export function buildConfigRoutes(deps: ConfigRouteDeps): WebRoute[] {
  const configRoute: WebRoute = {
    kind: "exact",
    path: ROUTES.config,
    handler: async (req, res) => {
      if (!guardLoopbackMethod(req, res, ["GET", "PUT"])) return;
      if (req.method === "GET") {
        const { user, revision } = deps.readUser();
        writeJson(res, 200, {
          ok: true,
          user,
          revision,
          effective: deps.resolve(),
          compress: deps.compress(),
          writable: deps.writable(),
        });
        return;
      }
      if (req.method === "PUT") {
        let body: unknown;
        try {
          body = await readBody(req, 64 * 1024);
        } catch (error) {
          const message = errorMessage(error);
          if (message.includes("invalid JSON body")) {
            writeJson(res, 400, {
              ok: false,
              error: { code: "invalid-json", details: `invalid JSON body: ${message}` },
            });
            return;
          }
          // 超限路径：readBody 已 reject 并 destroy 连接（socket 已断无法再写响应）。
          return;
        }
        const result = await applyConfigPatch(deps, body);
        if (!result.ok) {
          writeJson(res, result.status, {
            ok: false,
            error: { code: result.code, details: result.details },
          });
          return;
        }
        writeJson(res, 200, { ok: true, user: result.value.user, revision: result.value.revision });
        return;
      }
      writeJson(res, 405, { error: `method not allowed: ${req.method}` });
    },
  };
  return [configRoute];
}

/**
 * buildCaCertRoutes 的依赖注入面（apply 内装配；单测用 fake 直接构造）。
 *
 * 证书装配由 tls 域提供（loadDownloadableCertificate），本域不读证书文件、
 * 不引 tls 值——跨域值边在此终结，装配层组合两域（prepareTls 同口径）。
 */
export interface CaCertRouteDeps {
  /** 证书装配器（逐请求调用，tlsCaCertFile 热更新即时生效）。 */
  loadCertificate(format: "der" | "pem"): DownloadCertResult;
}

/**
 * 下发格式（显式白名单，无静默回落）：der（含 cer 别名，供 iOS 描述文件安装）/
 * pem（文本检查用）；缺失默认 der，未知值由调用方判 400（拼写错误不再静默
 * 当证书下发，fail-closed）。
 */
function parseCertFormat(url: string | undefined): "der" | "pem" | "invalid" {
  let format: string | null;
  try {
    format = new URL(url ?? "/", "http://lan-proxy.local").searchParams.get("format");
  } catch {
    return "invalid";
  }
  if (format === null || format === "der" || format === "cer") return "der";
  if (format === "pem") return "pem";
  return "invalid";
}

/**
 * 组装证书下发路由（GET 只读；loopback 围栏 + GET 白名单；无 Cookie 要求——
 * fresh 设备恰恰没有会话 Cookie，要求即鸡生蛋死锁；边界与 issue #380 同登记）。
 *
 * 本函数只做围栏 + 格式白名单 + 状态映射；证书三态装配（配 CA / 自签回退 /
 * 自定义无 CA 404）与文件读取解析全归 tls 域（loadDownloadableCertificate），
 * 失败码对固定文案（原文只进日志）。导出供单测（fake deps，不依赖网络）。
 */

/** 下发失败码对固定响应文案（P2-2：路径等内部信息不进响应）。 */
const DOWNLOAD_ERROR_DETAILS: Record<string, string> = {
  "ca-unconfigured":
    "未配置 CA 公钥（tlsCaCertFile 为空）：下发的证书无法建立信任。请先一键生成本地 CA（设置页），或配置 CA 公钥后重试。",
  "ca-unavailable": "证书暂不可用，请查看服务端日志",
  "ca-invalid": "证书文件无效（须为 CERTIFICATE PEM/DER），请查看服务端日志",
};
export function buildCaCertRoutes(deps: CaCertRouteDeps): WebRoute[] {
  const caCertRoute: WebRoute = {
    kind: "exact",
    path: ROUTES.caCert,
    handler: (req, res) => {
      if (!guardLoopbackMethod(req, res, ["GET"])) return;
      const format = parseCertFormat(req.url);
      if (format === "invalid") {
        writeJson(res, 400, {
          ok: false,
          error: { code: "bad-format", details: "format 非法（仅支持 der/cer/pem）" },
        });
        return;
      }
      const loaded = deps.loadCertificate(format);
      if (!loaded.ok) {
        writeJson(res, 404, {
          ok: false,
          error: { code: loaded.code, details: DOWNLOAD_ERROR_DETAILS[loaded.code] },
        });
        return;
      }
      // 二进制路由不用 writeJson（host-utils 只管 JSON），手写头：防嗅探 +
      // 附件下载 + 禁缓存（IP 变化即重签，缓存旧 CA 会误导排障）。
      res.writeHead(200, {
        "content-type": loaded.contentType,
        "content-disposition": 'attachment; filename="' + loaded.filename + '"',
        "content-length": loaded.body.length,
        "cache-control": "no-store",
        "x-content-type-options": "nosniff",
        "referrer-policy": "no-referrer",
      });
      res.end(loaded.body);
    },
  };
  return [caCertRoute];
}

