/**
 * dsh-lan-proxy — apply 的 launch token 提供者接线（src/server/apply.ts:118-173）。
 *
 * integration 层（ARCHITECTURE-METHOD §8）：真实 cordis 生命周期（fake ctx）+ 真实
 * 转发器 + fake 官方 connection 服务，锁住两段此前只在纯函数层或产物层有备份的接线：
 * 「connection.authenticatedUrl → token」的来源（createLanProxy 层的注入判据只证明
 * 「拿到 token 之后怎么用」，证明不了「token 从哪来」），以及「带 dsh 会话 cookie 的
 * 请求绝不注入 token」的排除分支（src/server/proxy/impl/proxy.ts 的 !hasDshAuthCookie）。
 * unit 层覆盖的是纯谓词 hasDshAuthCookie 与 withLaunchToken，e2e 覆盖组合语义但那是
 * 产物层、不进变异面——本层补的正是源码层的组合判据。
 *
 * 观测面：真实转发一次，看 fake 上游收到的 req.url。转发器端口不写死——apply 不返回
 * 句柄，故捕获其原生 console 出口的 `listening http://host:PORT` 行回读端口（apply
 * 用原生 console 而非 cordis logger，见 apply.ts:37-41），配 listen(0) 动态分配，避免
 * 固定端口在并发/残留进程下的 EADDRINUSE 假阳性。
 */
import { createServer, request as httpRequest } from "node:http";
import type { AddressInfo } from "node:net";
import { mkdtempSync, rmSync, readdirSync, readFileSync } from "node:fs";
import { request as httpsRequest } from "node:https";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { afterAll, beforeAll, describe, expect, it, onTestFailed, vi } from "vitest";

import { apply } from "../../src/server/apply.ts";

type LogEntry = { level: "info" | "warn"; text: string };
type Scenario = {
  home: string;
  upstreamUrls: string[];
  logs: LogEntry[];
  get: (headers?: Record<string, string>) => Promise<{ status: number | undefined; body: string }>;
  stop: () => Promise<void>;
};

const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));

/** 诊断输出：这一层的失败模式（端口占用、证书、上游连接）根因大多只出现在被测代码的
 *  console 输出里，失败时必须把它打出来，而不是只留一句「未在 8s 内启动转发器」。 */
const dumpLogs = (logs: LogEntry[]): string =>
  logs.length === 0 ? "（空）" : logs.map((l) => `[${l.level}] ${l.text}`).join("\n");

/**
 * 起一套 apply + 真实转发器 + fake 上游；connectionValue 即 inject 回调收到的服务。
 * config 覆盖 apply 的组合层配置（横幅用例靠它切 ownsHostCompat；缺省即插件默认态）。
 */
async function startScenario(
  connectionValue: unknown,
  config: Record<string, unknown> = {},
): Promise<Scenario> {
  const home = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-token-"));
  const prevHome = process.env.DSH_HOME;
  process.env.DSH_HOME = home;

  const upstreamUrls: string[] = [];
  const upstream = createServer((req, res) => {
    upstreamUrls.push(req.url ?? "");
    res.writeHead(200, { "content-type": "text/plain" });
    res.end("ok");
  });
  await new Promise<void>((r) => upstream.listen(0, "127.0.0.1", r));

  const logs: LogEntry[] = [];
  // vi.spyOn 而非裸赋值：裸赋值会盖住 vitest 自己的 per-test console 捕获（失败时看不到
  // 被测代码的原始输出），且手工还原容易漏——isolate: true 只保证不外溢，不保证会还。
  const logSpy = vi.spyOn(console, "log").mockImplementation((...a: unknown[]) => {
    logs.push({ level: "info", text: a.join(" ") });
  });
  const warnSpy = vi.spyOn(console, "warn").mockImplementation((...a: unknown[]) => {
    logs.push({ level: "warn", text: a.join(" ") });
  });

  const disposers: Array<() => void> = [];
  const ctx = {
    logger: { info: () => {}, warn: () => {}, error: () => {} },
    webServer: {
      port: (upstream.address() as AddressInfo).port,
      register: () => () => {},
      tapIndex: () => () => {},
    },
    inject(services: string[], fn: (c: unknown) => void) {
      if (services.includes("connection")) {
        fn({ connection: connectionValue, effect: (f: () => unknown) => f() });
      }
    },
    effect(fn: () => unknown) {
      const d = fn();
      if (typeof d === "function") disposers.push(d as () => void);
      return d;
    },
  };

  const stop = async (): Promise<void> => {
    logSpy.mockRestore();
    warnSpy.mockRestore();
    for (const d of disposers.reverse()) {
      try {
        d();
      } catch {}
    }
    await new Promise<void>((r) => upstream.close(() => r()));
    if (prevHome === undefined) delete process.env.DSH_HOME;
    else process.env.DSH_HOME = prevHome;
    rmSync(home, { recursive: true, force: true });
  };

  try {
    apply(ctx as unknown as Parameters<typeof apply>[0], {
      host: "127.0.0.1",
      port: 0,
      httpsEnabled: false,
      httpsPort: 0,
      enabled: true,
      ...config,
    });
    // 端口回读用轮询而非固定 sleep（防 flake 纪律）。
    const deadline = Date.now() + 8000;
    let listeningLine: string | undefined;
    while (Date.now() < deadline) {
      listeningLine = logs.find((l) => l.text.includes("listening http://"))?.text;
      if (listeningLine !== undefined) break;
      await sleep(20);
    }
    // 两种失败必须分开报：没起来（超时）与起来了但解析不出端口，修复方向完全不同。
    if (listeningLine === undefined) {
      throw new Error(
        `apply 未在 8s 内启动转发器（没有出现 listening 日志）。捕获到的 console 输出：\n${dumpLogs(logs)}`,
      );
    }
    const captured = /listening http:\/\/[^:]+:(\d+)/.exec(listeningLine)?.[1];
    const httpPort = captured === undefined ? Number.NaN : Number(captured);
    if (Number.isNaN(httpPort)) {
      throw new Error(
        `apply 打了 listening 日志但端口解析失败（期望 listening http://host:PORT）：${listeningLine}\n完整输出：\n${dumpLogs(logs)}`,
      );
    }
    const port = httpPort;
    return {
      home,
      upstreamUrls,
      logs,
      get: (headers: Record<string, string> = {}) =>
        new Promise((resolve, reject) => {
          const req = httpRequest(
            {
              hostname: "127.0.0.1",
              port,
              path: "/",
              method: "GET",
              headers: { host: "127.0.0.1:3081", ...headers },
            },
            (r) => {
              let body = "";
              r.on("data", (c) => (body += c));
              r.on("end", () => resolve({ status: r.statusCode, body }));
            },
          );
          req.on("error", reject);
          req.end();
        }),
      stop,
    };
  } catch (err) {
    await stop();
    throw err;
  }
}

describe("apply HTTPS 开关", () => {
  it("禁用 HTTPS 时不准备证书，HTTP 转发仍可用", async () => {
    const scenario = await startScenario({}, { httpsEnabled: false });
    try {
      expect(await scenario.get()).toEqual({ status: 200, body: "ok" });
      // HTTP ready 在 TLS 准备和 listen 完成之后；这里不靠等待时长证明没有落盘。
      expect(
        readdirSync(scenario.home, { recursive: true }).filter((name) =>
          /\.pem$/.test(String(name)),
        ),
      ).toEqual([]);
      expect(scenario.logs.filter((entry) => entry.text.includes("https https://"))).toEqual([]);
    } finally {
      await scenario.stop();
    }
  });

  it("启用 HTTPS 时通过 TLS 连接真实转发到上游", async () => {
    const scenario = await startScenario({}, { httpsEnabled: true });
    try {
      const line = scenario.logs.find((entry) => entry.text.includes("https https://"))?.text;
      expect(line).toBeDefined();
      const portText = /https https:\/\/[^:]+:(\d+)/.exec(line ?? "")?.[1];
      if (portText === undefined) throw new Error("HTTPS ready 未给出监听端口");
      const response = await new Promise<{ status: number | undefined; body: string }>(
        (resolve, reject) => {
          // 仅信任本场景自动生成的自签证书；真实握手及响应仍由 Node HTTPS 执行。
          const req = httpsRequest(
            {
              hostname: "127.0.0.1",
              port: Number(portText),
              path: "/",
              ca: readFileSync(
                join(scenario.home, "@wingsky-1", "dsh-lan-proxy", "dsh-lan-proxy-cert.pem"),
              ),
              agent: false,
            },
            (res) => {
              let body = "";
              res.setEncoding("utf8");
              res.on("data", (chunk: string) => {
                body += chunk;
              });
              res.on("error", reject);
              res.on("end", () => resolve({ status: res.statusCode, body }));
            },
          );
          req.setTimeout(5000, () => req.destroy(new Error("HTTPS 请求超时")));
          req.on("error", reject);
          req.end();
        },
      );
      expect(response).toEqual({ status: 200, body: "ok" });
      expect(scenario.upstreamUrls).toEqual(["/"]);
    } finally {
      await scenario.stop();
    }
  });
});

type ScenarioSpec = {
  label: string;
  title: string;
  connection: unknown;
  expectedUrl: string;
  /** 请求头；cookie 排除场景靠它带 dsh 会话 cookie。 */
  headers?: Record<string, string>;
};

const NO_COOKIE_TITLE = "无会话 cookie 的 GET / 到达上游时的 URL 符合接线预期";

const SCENARIOS: ScenarioSpec[] = [
  {
    label: "authenticatedUrl 返回带 token 的 URL → 上游收到该 token",
    title: NO_COOKIE_TITLE,
    connection: { authenticatedUrl: () => "http://lan-proxy.local/?token=minted-826" },
    expectedUrl: "/?token=minted-826",
  },
  {
    label: "authenticatedUrl 返回不带 token 的 URL → 不注入",
    title: NO_COOKIE_TITLE,
    connection: { authenticatedUrl: () => "http://lan-proxy.local/" },
    expectedUrl: "/",
  },
  {
    label: "authenticatedUrl 抛异常 → 降级为不注入",
    title: NO_COOKIE_TITLE,
    connection: {
      authenticatedUrl: () => {
        throw new Error("connection boom");
      },
    },
    expectedUrl: "/",
  },
  {
    label: "connection 服务缺少 authenticatedUrl → 不注入",
    title: NO_COOKIE_TITLE,
    connection: { rpc: {} },
    expectedUrl: "/",
  },
  {
    // 排除分支（proxy.ts 的 !hasDshAuthCookie）在源码层此前无备份：unit 只测纯谓词，
    // e2e 测组合语义但 e2e 是产物层且不进变异面。取反本分支即可打红这一条。
    label: "带 dsh 会话 cookie → 绝不注入 token（防有效 cookie 无限 303）",
    title: "带 dsh 会话 cookie 的 GET / 到达上游时未被注入 token",
    connection: { authenticatedUrl: () => "http://lan-proxy.local/?token=minted-826" },
    expectedUrl: "/",
    headers: { cookie: "dsh-auth-web=still-valid" },
  },
];

// ownsHostCompat 状态行（P2-1）：这条横幅此前无任何断言，CI 变异日志里留下存活体。
// 默认态与开启态各断言一次——两者是横幅里唯一把这个开关讲给操作者的地方（故障态下
// 设置卡片不挂载，见 README 安全模型的「已知限制」）。
describe("integration: 启动横幅的 ownsHostCompat 状态行", () => {
  const bannerScenario = { rpc: {} };
  let offScenario: Scenario | undefined;
  let onScenario: Scenario | undefined;

  beforeAll(async () => {
    offScenario = await startScenario(bannerScenario);
    onScenario = await startScenario(bannerScenario, { ownsHostCompat: true });
  }, 60_000);

  afterAll(async () => {
    if (offScenario !== undefined) await offScenario.stop();
    if (onScenario !== undefined) await onScenario.stop();
  });

  it("默认态横幅含 ownsHostCompat: OFF", () => {
    const current = offScenario;
    if (current === undefined) throw new Error("scenario 未建立");
    expect(current.logs.some((l) => l.text.includes("ownsHostCompat: OFF"))).toBe(true);
  });

  it("ownsHostCompat: true 时横幅含 ownsHostCompat: ON", () => {
    const current = onScenario;
    if (current === undefined) throw new Error("scenario 未建立");
    expect(current.logs.some((l) => l.text.includes("ownsHostCompat: ON"))).toBe(true);
  });
});

for (const sc of SCENARIOS) {
  describe(`integration: apply launch token 提供者 — ${sc.label}`, () => {
    let scenario: Scenario | undefined;
    beforeAll(async () => {
      scenario = await startScenario(sc.connection);
    }, 30_000);
    afterAll(async () => {
      if (scenario !== undefined) await scenario.stop();
    });
    it(sc.title, async () => {
      const current = scenario;
      if (current === undefined) throw new Error("scenario 未建立");
      // 断言失败时把被测代码的 console 输出打出来（onTestFailed 只能在测试体内注册；
      // 此时 console 仍被 spy 着，而 console.error 不在 spy 面内，能直达失败输出）。
      onTestFailed(() => {
        console.error(`[scenario 捕获的 console 输出]\n${dumpLogs(current.logs)}`);
      });
      const res = await current.get(sc.headers);
      expect(res.status).toBe(200);
      // body 此前只被收集、从未断言；fake 上游恒定回 "ok"，这条断言覆盖「响应体真的
      // 从上游原样穿过转发层」这一段（不再留装饰性数据）。
      expect(res.body).toBe("ok");
      expect(current.upstreamUrls.at(-1)).toBe(sc.expectedUrl);
    });
  });
}

packages/dsh-lan-proxy/test/unit/unit-ho.source:
/**
 * dsh-lan-proxy — 宿主端 host trust 兼容注入的直连判据（issue #856，src 层）。
 *
 * 判据分两段：
 * 1. 纯函数 `applyHostTrustInjection`：在 `node:vm` 里**真执行**注入脚本，证明
 *    「非回环才写 / 预置 transport 的字段存活 / 幂等 / 关时逐字节不变」——整体赋值
 *    与 `kind: "global"` 行这两种写法都会在这里被打红；
 * 2. apply 接线：tap 只在顶层注册一次（跨多次 sync）、开关逐请求读取、dispose 后消失。
 *
 * 顺序不变量用官方纯函数 `renderIndexInjections` 锁：真实链是「结构化注入表 →
 * tap」，故断言注入落在官方 boot-readiness 尾脚本（`__DSH_BOOT_READY__`）之前，
 * 而不是手写期望位置。
 */
import { mkdtempSync, rmSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { createContext, runInContext } from "node:vm";

import { describe, expect, it, vi } from "vitest";
import type { Context } from "@deepseek-ai/cordis";
import { renderIndexInjections } from "@deepseek-ai/dsh-host-webserver";

import { apply } from "../../src/server/apply.ts";
import { SETTINGS_NS } from "../../src/server/config/impl/namespace.ts";
import {
  applyHostTrustInjection,
  HOST_TRUST_ELEMENT_ID,
  HOST_TRUST_RUNTIME_MARKER,
} from "../../src/server/host-trust/impl/injection.ts";

/** 与 `dsh-web-frontend/dist/index.html` 同形的 index（module 入口在 head 内）。 */
const RAW_INDEX = [
  "<!doctype html>",
  '<html lang="en">',
  "  <head>",
  '    <meta charset="utf-8" />',
  "    <title>DeepSeek Harness</title>",
  '    <script type="module" crossorigin src="./assets/index-abc.js"></script>',
  "  </head>",
  "  <body>",
  '    <div id="root"></div>',
  "  </body>",
  "</html>",
].join("\n");

const SCRIPT_OPEN = `<script id="${HOST_TRUST_ELEMENT_ID}">`;

/** 取出注入脚本正文（不含 script 标签）。 */
function injectedScript(html: string): string {
  const at = html.indexOf(SCRIPT_OPEN);
  if (at === -1) throw new Error("注入脚本不存在");
  const start = at + SCRIPT_OPEN.length;
  const end = html.indexOf("</script>", start);
  return html.slice(start, end);
}

/**
 * vm realm 全局：location 恒有；注入脚本按条件写 `__DSH_TRANSPORT__`/marker。
 * transport 按存在声明（未写时读到 undefined）：realm 是动态全局，逐处收窄要给 6 处
 * 断言加噪，而缺失读到的 undefined 本就是部分断言的期望值，行为零差异。
 */
interface InjectedRealm {
  location: { hostname: string };
  __DSH_TRANSPORT__: Record<string, unknown>;
  [key: string]: unknown;
}

/**
 * 在 `node:vm` 里执行注入脚本，返回该 realm 的全局对象。
 * `hostname` 模拟 `location.hostname`；`transport` 非 undefined 时预置前序 transport。
 */
function runInjectedScript(
  html: string,
  options: { hostname: string; transport?: Record<string, unknown> },
): InjectedRealm {
  const sandbox = { location: { hostname: options.hostname } } as InjectedRealm;
  if (options.transport !== undefined) sandbox.__DSH_TRANSPORT__ = options.transport;
  runInContext(injectedScript(html), createContext(sandbox));
  return sandbox;
}

describe("applyHostTrustInjection：自条件注入（node:vm 真执行）", () => {
  it("开关关闭时逐字节原样返回", () => {
    expect(applyHostTrustInjection(RAW_INDEX, false)).toBe(RAW_INDEX);
  });

  it("注入落在 head 内", () => {
    const out = applyHostTrustInjection(RAW_INDEX, true);
    expect(out.indexOf(SCRIPT_OPEN)).toBeGreaterThan(out.indexOf("<head>"));
    expect(out.indexOf(SCRIPT_OPEN)).toBeLessThan(out.indexOf("</head>"));
  });

  it("注入是经典内联脚本（无 type/src，故在 deferred module 入口执行前跑完）", () => {
    const out = applyHostTrustInjection(RAW_INDEX, true);
    const tagEnd = out.indexOf(">", out.indexOf(SCRIPT_OPEN)) + 1;
    expect(out.slice(out.indexOf(SCRIPT_OPEN), tagEnd)).toBe(SCRIPT_OPEN);
  });

  it("顺序不变量：与官方结构化注入表合链后，注入先于 boot-readiness 尾脚本", () => {
    const rows = [
      { kind: "script" as const, placement: "head" as const, text: "globalThis.__probeHead = 1;" },
      { kind: "script" as const, placement: "body" as const, text: "globalThis.__probeBody = 1;" },
    ];
    const rendered = applyHostTrustInjection(renderIndexInjections(RAW_INDEX, rows), true);
    const trustAt = rendered.indexOf(SCRIPT_OPEN);
    const readyAt = rendered.indexOf("__DSH_BOOT_READY__");
    expect(trustAt).toBeGreaterThan(-1);
    expect(readyAt).toBeGreaterThan(-1);
    expect(trustAt).toBeLessThan(readyAt);
    // 仍必须在 head 内（body 注入晚于 boot-readiness 尾脚本）
    expect(trustAt).toBeLessThan(rendered.indexOf("</head>"));
  });

  it("幂等：两次应用只注入一次", () => {
    const once = applyHostTrustInjection(RAW_INDEX, true);
    const twice = applyHostTrustInjection(once, true);
    expect(twice).toBe(once);
    expect(twice.split(SCRIPT_OPEN).length - 1).toBe(1);
  });

  it("预置前序 transport 时其字段存活（绝不整体覆盖）", () => {
    const prior = { ownsHost: false, fetch: () => "prior-fetch", custom: 42 };
    const out = applyHostTrustInjection(RAW_INDEX, true);
    const g = runInjectedScript(out, { hostname: "192.168.1.50", transport: prior });
    expect(g.__DSH_TRANSPORT__).toBe(prior);
    expect(g.__DSH_TRANSPORT__.ownsHost).toBe(false);
    expect(g.__DSH_TRANSPORT__.custom).toBe(42);
    expect(typeof g.__DSH_TRANSPORT__.fetch).toBe("function");
    // 未写 transport 就不该落 marker——观测器据此区分「生效」与「未生效」
    expect(g[HOST_TRUST_RUNTIME_MARKER]).toBeUndefined();
  });

  it("非回环页且无前序 transport 时写入 ownsHost 并落 marker", () => {
    const g = runInjectedScript(applyHostTrustInjection(RAW_INDEX, true), {
      hostname: "192.168.1.50",
    });
    expect(g.__DSH_TRANSPORT__.ownsHost).toBe(true);
    expect(Object.keys(g.__DSH_TRANSPORT__)).toEqual(["ownsHost"]);
    expect(g[HOST_TRUST_RUNTIME_MARKER]).toBe(true);
  });

  const loopbackHostnames = ["localhost", "[::1]", "127.0.0.1", "127.9.9.9"];
  it.each(loopbackHostnames)("回环 authority %s 不写入任何东西", (hostname) => {
    const g = runInjectedScript(applyHostTrustInjection(RAW_INDEX, true), { hostname });
    expect(g.__DSH_TRANSPORT__).toBeUndefined();
    expect(g[HOST_TRUST_RUNTIME_MARKER]).toBeUndefined();
  });

  const nonLoopbackHostnames = ["192.168.1.50", "10.0.0.7", "127.0.0.1.evil.example", "128.0.0.1"];
  it.each(nonLoopbackHostnames)("非回环 authority %s 照常写入", (hostname) => {
    const g = runInjectedScript(applyHostTrustInjection(RAW_INDEX, true), { hostname });
    expect(g.__DSH_TRANSPORT__.ownsHost).toBe(true);
  });
});

/** fake ctx：捕获 effect（含 label）、tapIndex 变换与 index-inject 订阅。 */
function makeHostTrustCtx() {
  const state: Record<string, unknown> = { enabled: false, ownsHostCompat: false };
  // document-updated 监听器（接缝内部订阅；触发时带 ns+revision，与官方事件同形）。
  const watchers: Array<(ns?: unknown, revision?: unknown) => void> = [];
  // tap 带注册时的 effect label：只有这样才能在开关为关时仍识别出 host trust tap。
  const taps: Array<{ label: string; run: (html: string) => string }> = [];
  const effects: Array<{ label: string; dispose: () => void }> = [];
  const injectListeners: Array<(table: unknown[]) => void> = [];
  const routes: Array<{ path: string }> = [];
  let activeLabel = "";
  const ctx = {
    logger: { info() {}, warn() {}, error() {} },
    webServer: {
      port: 3080,
      register(route: { path: string }) {
        routes.push(route);
        return () => {};
      },
      tapIndex(transform: (html: string) => string) {
        taps.push({ label: activeLabel, run: transform });
        return () => {
          const at = taps.findIndex((entry) => entry.run === transform);
          if (at !== -1) taps.splice(at, 1);
        };
      },
      on(event: string, cb: (table: unknown[]) => void) {
        if (event === "webserver/index-inject") injectListeners.push(cb);
        return () => {};
      },
    },
    inject(services: string[], fn: (c: unknown) => void) {
      if (services.includes("settings")) {
        fn({
          settings: {
            describe: () => [{ ns: SETTINGS_NS, value: { ...state }, revision: 0 }],
          },
          effect: (f: () => unknown) => f(),
          on: (event: string, cb: (ns?: unknown, revision?: unknown) => void) => {
            if (event === "settings/document-updated") watchers.push(cb);
            return () => {};
          },
        });
      }
    },
    effect(fn: () => unknown, label: string) {
      activeLabel = label;
      let d: unknown;
      try {
        d = fn();
      } finally {
        activeLabel = "";
      }
      if (typeof d === "function") effects.push({ label, dispose: d as () => void });
      return d;
    },
  };
  return { ctx, state, watchers, taps, effects, injectListeners, routes };
}

describe("apply 接线：host trust tap 的生命周期纪律", () => {
  it("跨多次 sync 只注册一次；开关逐请求读取；不污染注入表；dispose 后注入消失", () => {
    const home = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-host-trust-"));
    const prevHome = process.env.DSH_HOME;
    process.env.DSH_HOME = home;
    vi.useFakeTimers();
    try {
      const h = makeHostTrustCtx();
      apply(h.ctx as unknown as Context, {
        enabled: false,
        httpsEnabled: false,
        printBanner: false,
      });

      const hostTrustTaps = () => h.taps.filter((entry) => entry.label === "lan-proxy: host trust");
      const hostTrustEffects = () => h.effects.filter((e) => e.label === "lan-proxy: host trust");

      expect(hostTrustEffects().length).toBe(1);
      expect(hostTrustTaps().length).toBe(1);

      // 默认关：同一 tap 的输出逐字节不变
      const tap = hostTrustTaps()[0].run;
      expect(tap(RAW_INDEX)).toBe(RAW_INDEX);

      // 两次 sync 触发（document-updated → 3s 防抖）：tap 数与 effect 数都不得增长。
      // 每次触发前改值，快照比对才判定为变化（同值重放等价忽略）。
      h.state.tick = 1;
      for (const cb of h.watchers) cb(SETTINGS_NS, 1);
      vi.advanceTimersByTime(3000);
      h.state.tick = 2;
      for (const cb of h.watchers) cb(SETTINGS_NS, 2);
      vi.advanceTimersByTime(3000);
      expect(hostTrustTaps().length).toBe(1);
      expect(hostTrustEffects().length).toBe(1);

      // 开关按请求读取：同一个 tap 立即随配置变化（未重建）
      h.state.ownsHostCompat = true;
      expect(tap(RAW_INDEX)).toContain(HOST_TRUST_ELEMENT_ID);
      h.state.ownsHostCompat = false;
      expect(tap(RAW_INDEX)).toBe(RAW_INDEX);

      // 官方结构化注入表不被本插件写行（global 行会整体覆盖 transport）
      const table: unknown[] = [];
      for (const cb of h.injectListeners) cb(table);
      expect(table).toEqual([]);

      // dispose 后注入消失
      for (const e of [...h.effects].reverse()) {
        try {
          e.dispose();
        } catch {}
      }
      expect(hostTrustTaps().length).toBe(0);
    } finally {
      vi.useRealTimers();
      process.env.DSH_HOME = prevHome;
      rmSync(home, { recursive: true, force: true });
    }
  });
});

describe("apply 接线：randomUUID polyfill tap（entry 段补强）", () => {
  it("head 内幂等注入且含 randomUUID 回退实现", () => {
    const home = mkdtempSync(join(tmpdir(), "dsh-lan-proxy-polyfill-"));
    const prevHome = process.env.DSH_HOME;
    process.env.DSH_HOME = home;
    try {
      const h = makeHostTrustCtx();
      apply(h.ctx as unknown as Context, {
        enabled: false,
        httpsEnabled: false,
        printBanner: false,
      });
      const taps = h.taps.filter((entry) => entry.label === "lan-proxy: randomUUID polyfill");
      expect(taps.length).toBe(1);
      const once = taps[0].run(RAW_INDEX);
      expect(once).toContain("__dshRandomUuidPolyfill__");
      expect(once).toContain("crypto.randomUUID");
      expect(once.indexOf("__dshRandomUuidPolyfill__")).toBeLessThan(once.indexOf("</head>"));
      expect(taps[0].run(once)).toBe(once);
    } finally {
      process.env.DSH_HOME = prevHome;
      rmSync(home, { recursive: true, force: true });
    }
  });
});

